example.code:
 // In Contoso.TestInfra.dll
 [assembly: AssemblyFixtureProvider(typeof(GlobalFixtures))]

 public static class GlobalFixtures
 {
     [AssemblyInitialize]
     public static void Init(TestContext context) { /* ... */ }

     [AssemblyCleanup]
     public static void Cleanup() { /* ... */ }
 }

 [TestClass]
 public class CheckoutTests
 {
     [TestMethod]
     public void CreateCart() { }

     // Fan-out: both of these wait for CreateCart, then may run in parallel with each other.
     [TestMethod]
     [DependsOn(nameof(CreateCart))]
     public void AddItem() { }

     [TestMethod]
     [DependsOn(nameof(CreateCart))]
     public void ApplyCoupon() { }

     // Fan-in: waits for both.
     [TestMethod]
     [DependsOn(nameof(AddItem))]
     [DependsOn(nameof(ApplyCoupon))]
     public void Checkout() { }

     // Runs even when its prerequisite failed.
     [TestMethod]
     [DependsOn(nameof(Checkout), ProceedOnFailure = true)]
     public void WriteAuditRecord() { }
 }

 [assembly: TestFilterProvider(typeof(NightlyFilter))]

 public sealed class NightlyFilter : ITestFilter
 {
     public TestFilterResult Filter(TestFilterContext context)
         => context.Categories.Contains("Nightly")
             && Environment.GetEnvironmentVariable("RUN_NIGHTLY") != "1"
             ? TestFilterResult.Skip("Set RUN_NIGHTLY=1 to run nightly tests.")
             : TestFilterResult.Run;
 }

 [assembly: TestFilterProvider<NightlyFilter>]

 public sealed class NightlyFilter : ITestFilter
 {
     public TestFilterResult Filter(TestFilterContext context)
         => context.Categories.Contains("Nightly")
             && Environment.GetEnvironmentVariable("RUN_NIGHTLY") != "1"
             ? TestFilterResult.Skip("Set RUN_NIGHTLY=1 to run nightly tests.")
             : TestFilterResult.Run;
 }

